
const main = document.querySelector(".main");
const dashboardHTML = main.innerHTML;

let tasks = JSON.parse(localStorage.getItem("unipilot_tasks") || "[]");

function saveTasks() {
  localStorage.setItem("unipilot_tasks", JSON.stringify(tasks));
  }

  function showDashboard() {
    main.innerHTML = dashboardHTML;
      document.querySelector(".topbar h2").textContent = "Dashboard";
      }

      function showTasks() {
        main.innerHTML = `
            <header class="topbar">
                  <div>
                          <span class="eyebrow">STAY ORGANIZED</span>
                                  <h2>My Tasks</h2>
                                        </div>
                                              <div class="avatar">U</div>
                                                  </header>

                                                      <section class="welcome">
                                                            <div>
                                                                    <span class="eyebrow">YOUR ACADEMIC PLANNER</span>
                                                                            <h1>One task at a time<span>.</span></h1>
                                                                                    <p>Manage assignments, practicals, projects and exams.</p>
                                                                                          </div>
                                                                                                <div class="welcome-symbol">✓</div>
                                                                                                    </section>

                                                                                                        <section class="task-stats">
                                                                                                              <div class="panel">
                                                                                                                      <small>Total Tasks</small>
                                                                                                                              <h2 id="total-count">0</h2>
                                                                                                                                    </div>
                                                                                                                                          <div class="panel">
                                                                                                                                                  <small>Pending</small>
                                                                                                                                                          <h2 id="pending-count">0</h2>
                                                                                                                                                                </div>
                                                                                                                                                                      <div class="panel">
                                                                                                                                                                              <small>Completed</small>
                                                                                                                                                                                      <h2 id="completed-count">0</h2>
                                                                                                                                                                                            </div>
                                                                                                                                                                                                </section>

                                                                                                                                                                                                    <section class="panel task-manager">
                                                                                                                                                                                                          <h3>Add a New Task</h3>
                                                                                                                                                                                                                <p class="muted">Keep track of your academic responsibilities.</p>

                                                                                                                                                                                                                      <form id="task-form">
                                                                                                                                                                                                                              <label for="task-title">Task name</label>
                                                                                                                                                                                                                                      <input id="task-title" type="text"
                                                                                                                                                                                                                                                placeholder="Example: Complete DBMS assignment" required>

                                                                                                                                                                                                                                                        <label for="task-category">Category</label>
                                                                                                                                                                                                                                                                <select id="task-category">
                                                                                                                                                                                                                                                                          <option>Assignment</option>
                                                                                                                                                                                                                                                                                    <option>Practical</option>
                                                                                                                                                                                                                                                                                              <option>Project</option>
                                                                                                                                                                                                                                                                                                        <option>Exam Preparation</option>
                                                                                                                                                                                                                                                                                                                  <option>Other</option>
                                                                                                                                                                                                                                                                                                                          </select>

                                                                                                                                                                                                                                                                                                                                  <label for="task-date">Deadline</label>
                                                                                                                                                                                                                                                                                                                                          <input id="task-date" type="date">

                                                                                                                                                                                                                                                                                                                                                  <button class="primary-button" type="submit">
                                                                                                                                                                                                                                                                                                                                                            + Add Task
                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                          </form>
                                                                                                                                                                                                                                                                                                                                                                              </section>

                                                                                                                                                                                                                                                                                                                                                                                  <section class="panel task-manager">
                                                                                                                                                                                                                                                                                                                                                                                        <div class="panel-heading">
                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                          <h3>Your Task List</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                    <p class="muted">Track your progress.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <div id="task-list"></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                            </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                <footer>© 2026 UniPilot · Built for students.</footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                  `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("task-form").addEventListener("submit", function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                            const title = document.getElementById("task-title").value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                const category = document.getElementById("task-category").value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const date = document.getElementById("task-date").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!title) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tasks.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  id: Date.now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              category,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    date,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          completed: false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  saveTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      this.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          renderTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              renderTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function renderTasks() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const total = tasks.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const completed = tasks.filter(task => task.completed).length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const pending = total - completed;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById("total-count").textContent = total;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("pending-count").textContent = pending;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById("completed-count").textContent = completed;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const list = document.getElementById("task-list");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (total === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  list.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="empty-state">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>✦</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h3>No tasks yet</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p>Add your first academic task above!</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  list.innerHTML = tasks.map(task => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="task-item ${task.completed ? "done" : ""}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="task-info">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <strong>${escapeHTML(task.title)}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <small>${escapeHTML(task.category)} · ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      task.date ? escapeHTML(task.date) : "No deadline"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="task-actions">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button class="complete-btn" data-complete="${task.id}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ${task.completed ? "Undo" : "Complete"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="delete-btn" data-delete="${task.id}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Delete
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          `).join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            list.querySelectorAll("[data-complete]").forEach(button => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const task = tasks.find(t => t.id === Number(button.dataset.complete));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            task.completed = !task.completed;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  saveTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                list.querySelectorAll("[data-delete]").forEach(button => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tasks = tasks.filter(t => t.id !== Number(button.dataset.delete));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                saveTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function escapeHTML(value) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return String(value).replace(/[&<>"']/g, char => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "&": "&amp;",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "<": "&lt;",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ">": "&gt;",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '"': "&quot;",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "'": "&#39;"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })[char]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.addEventListener("click", function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const button = e.target.closest("[data-page]");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const page = button.dataset.page;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll(".nav-item").forEach(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                item.classList.toggle("active", item.dataset.page === page);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (page === "dashboard") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        showDashboard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (page === "tasks") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              showTasks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const names = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          pdf: "PDF Studio",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                converter: "File Converter",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      scanner: "Smart Scanner",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            documents: "Document Creator",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  files: "My Files",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ai: "AI Copilot"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert(names[page] + " is our next development module!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  